# Generated by evals/sync.py — edit the source, not this copy.
"""Verifier harness shared by every Harbor task in this folder.

Stdlib only, on purpose: the eval image needs nothing but `python3`, so there
is no pip install in the grading path to go slow or go wrong.

Each task's `test_site.py` builds a `Scorecard`, asserts the things that are
specific to its brief, and calls `finish()`. `finish()` combines those content
assertions with the structural report from `sitecheck.py` and writes
`/logs/verifier/reward.json`.

Three metrics land in LangSmith as separate feedback keys:

  * `structure` — did it produce a working page at all (sitecheck errors)
  * `content`   — did it produce what the brief actually asked for
  * `reward`    — the weighted headline number, 40/60 structure/content

Splitting them is what makes an experiment readable. A run that scores 1.0 on
structure and 0.3 on content built a clean page for the wrong brief, and that
is a different failure from markup that does not parse.
"""

from __future__ import annotations

import json
import re
import sys
from html.parser import HTMLParser
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))

from sitecheck import check_site, format_report  # noqa: E402

REWARD_DIR = Path("/logs/verifier")

# Copy that means the agent stopped short of writing real content.
PLACEHOLDERS = [
    "lorem ipsum", "your business name", "your company", "company name here",
    "todo", "tbd", "placeholder", "insert text", "coming soon…", "xxx",
    "[name]", "[address]", "[phone]",
]


class _Strip(HTMLParser):
    """Visible text only — no markup, no script/style bodies."""

    def __init__(self) -> None:
        super().__init__(convert_charrefs=True)
        self.parts: list[str] = []
        self._skip = False

    def handle_starttag(self, tag, attrs):
        if tag in {"script", "style"}:
            self._skip = True

    def handle_endtag(self, tag):
        if tag in {"script", "style"}:
            self._skip = False

    def handle_data(self, data):
        if not self._skip:
            self.parts.append(data)

    def text(self) -> str:
        return re.sub(r"\s+", " ", "".join(self.parts)).strip()


def plain_text(html: str) -> str:
    parser = _Strip()
    parser.feed(html)
    return parser.text()


class Site:
    """The site under test, loaded once."""

    def __init__(self, root: str | Path) -> None:
        self.root = Path(root)
        self.pages: dict[str, str] = {}
        self.styles: dict[str, str] = {}
        if self.root.is_dir():
            for path in sorted(self.root.rglob("*.html")):
                self.pages[path.relative_to(self.root).as_posix()] = path.read_text(
                    encoding="utf-8", errors="replace"
                )
            for path in sorted(self.root.rglob("*.css")):
                self.styles[path.relative_to(self.root).as_posix()] = path.read_text(
                    encoding="utf-8", errors="replace"
                )

    @property
    def html(self) -> str:
        """Every page's markup concatenated — for site-wide regex checks."""
        return "\n".join(self.pages.values())

    @property
    def css(self) -> str:
        return "\n".join(self.styles.values())

    def text(self, page: str | None = None) -> str:
        """Visible text of one page, or of the whole site."""
        if page is not None:
            return plain_text(self.pages.get(page, ""))
        return plain_text(self.html)

    def nav_links(self, page: str) -> list[str]:
        """hrefs inside the page's <nav>, in document order."""
        match = re.search(r"<nav\b[^>]*>(.*?)</nav>", self.pages.get(page, ""), re.S | re.I)
        if not match:
            return []
        return re.findall(r'href\s*=\s*["\']([^"\']+)["\']', match.group(1), re.I)

    def has_placeholder(self) -> str | None:
        haystack = self.text().lower()
        for token in PLACEHOLDERS:
            if token in haystack:
                return token
        return None


class Scorecard:
    """Content assertions for one task, plus the shared structural report."""

    def __init__(self, site: Site) -> None:
        self.site = site
        self.results: list[tuple[str, bool, str]] = []

    def check(self, name: str, passed: bool, detail: str = "") -> bool:
        self.results.append((name, bool(passed), detail))
        return bool(passed)

    def check_no_placeholders(self) -> bool:
        found = self.site.has_placeholder()
        return self.check(
            "no placeholder copy",
            found is None,
            f"found {found!r}" if found else "",
        )

    def check_shared_nav(self, expected_pages: list[str]) -> bool:
        """Every page carries the same nav, and it reaches every page."""
        navs = {page: self.site.nav_links(page) for page in expected_pages}
        missing = [p for p, links in navs.items() if not links]
        if missing:
            return self.check("shared nav on every page", False, f"no <nav> in {', '.join(missing)}")

        sets = {p: frozenset(link.split("/")[-1] or "index.html" for link in links) for p, links in navs.items()}
        identical = len(set(sets.values())) == 1
        reaches = all(
            any(page.split("/")[-1] in targets for targets in sets.values())
            for page in expected_pages
        )
        return self.check(
            "shared nav on every page",
            identical and reaches,
            "" if identical and reaches else f"nav differs across pages: {dict(sets)}",
        )

    def finish(self, weight_structure: float = 0.4) -> int:
        """Score, write reward.json, print a report. Returns a process exit code."""
        report = check_site(self.site.root)
        errors = len(report["errors"])
        if not report["pages"]:
            # Nothing was built. `check_site` reports that as a single error,
            # which the scale below would score at 0.875 — so short-circuit it.
            structure = 0.0
        else:
            # Otherwise errors are capped rather than binary: a page with one
            # missing alt attribute is not the same failure as one that does
            # not parse.
            structure = max(0.0, 1.0 - errors / 8.0)

        passed = sum(1 for _, ok, _ in self.results if ok)
        content = passed / len(self.results) if self.results else 0.0
        reward = weight_structure * structure + (1 - weight_structure) * content

        print(format_report(report))
        print(f"\nContent assertions — {passed}/{len(self.results)} passed:")
        for name, ok, detail in self.results:
            print(f"  [{'PASS' if ok else 'FAIL'}] {name}{f' — {detail}' if detail and not ok else ''}")
        print(
            f"\nstructure={structure:.3f} ({errors} error(s))  "
            f"content={content:.3f}  reward={reward:.3f}"
        )

        metrics = {
            "reward": round(reward, 4),
            "structure": round(structure, 4),
            "content": round(content, 4),
            "structural_errors": errors,
            "structural_warnings": len(report["warnings"]),
        }
        try:
            REWARD_DIR.mkdir(parents=True, exist_ok=True)
            (REWARD_DIR / "reward.json").write_text(json.dumps(metrics, indent=2))
        except OSError as exc:
            # Running the verifier on a laptop, where /logs is not writable.
            print(f"\n(not writing {REWARD_DIR}/reward.json: {exc})")
        return 0 if reward >= 0.999 else 1


def site_from_argv() -> Site:
    """The site root: argv[1], else /site."""
    return Site(sys.argv[1] if len(sys.argv) > 1 else "/site")
